  async getDailyHeadlines(): Promise<any[]> {
    const modelId = 'gemini-2.5-flash';

    const systemPrompt = `
      Actúa como un jefe de redacción de tecnología y noticias globales.
      Tu tarea es identificar las 4 noticias MÁS IMPORTANTES y VIRALES que han ocurrido en las últimas 24 horas.

