          "title": "Título impactante y corto (Máx 10 palabras)",
          "sourceUrl": "URL real y verificada de la fuente de la noticia (Encuéntrala usando Google Search)"
        }
      ]

      IMPORTANTE:
      - Solo devuelve el JSON.
      - Deben ser hechos reales y recientes.
      - ES OBLIGATORIO validar que la 'sourceUrl' sea un enlace real y funcional encontrado en la búsqueda.
    `;

    try {
      const client = this.getAiClient();
      const response = await client.models.generateContent({
        model: modelId,
        contents: [
          { role: 'user', parts: [{ text: systemPrompt }] }
        ],
        config: {
          temperature: 0.4,
          tools: [{ googleSearch: {} }]
        }
      });

      const text = response.text;
      if (!text) return [];

      let jsonString = text;
      const jsonMatch = text.match(/```json\s*([\s\S]*?)\s*```/) || text.match(/```\s*([\s\S]*?)\s*```/);
      if (jsonMatch) {
        jsonString = jsonMatch[1];
      }

      try {
        return JSON.parse(jsonString);
      } catch (e) {
        console.error('Error parsing headlines JSON:', e);
        return [];
      }
    } catch (error) {
      console.error('Error getting daily headlines:', error);
      return [];
    }
